\begin{axiom}[Scheme of Separation] For every formula $\phi(x)$, this is an
axiom: for any $A$, the set $\Setabs{x \in A}{\phi(x)}$ exists.
\end{axiom}

target:
\begin{axiom}[د بېلونې شېما] د هر فارمول $\phi(x)$ دپاره دا يو
بديهي اصل دے: د هر $A$ دپاره سټ $\Setabs{x \in A}{\phi(x)}$ شتون لري.
\end{axiom}

source:
\begin{thm}\ollabel{thm:NoUniversalSet}
There is no \emph{universal} set, i.e., $\Setabs{x}{x = x}$ does not exist.
\end{thm}

target:
\begin{thm}\ollabel{thm:NoUniversalSet}
هېڅ \emph{عمومي} سټ نۀ شته، يعنې $\Setabs{x}{x = x}$ شتون نۀ لري.
\end{thm}

source:
\begin{proof}
For reductio, suppose $V$ is a universal set. Then by Separation, $R =
\Setabs{x \in V}{x \notin x} = \Setabs{x}{x \notin x}$ exists,
contradicting Russell's Paradox.
\end{proof}

target:
\begin{proof}
د تناقض له لارې د ثبوت دپاره فرض کړئ چې $V$ يو عمومي سټ دے.
نو د بېلونې له مخې $R =
\Setabs{x \in V}{x \notin x} = \Setabs{x}{x \notin x}$ شتون لري،
چې د رسل له تناقض سره ټکر کوي.
\end{proof}

source:
\begin{prop}\ollabel{prop:emptyexists}
If any set exists, then $\emptyset$ exists.
\end{prop}

target:
\begin{prop}\ollabel{prop:emptyexists}
که کوم سټ شتون ولري، نو $\emptyset$ شتون لري.
\end{prop}

source:
\begin{proof}
If $A$ is a set, $\emptyset = \Setabs{x \in A}{x \neq x}$ exists by Separation.
\end{proof}

target:
\begin{proof}
که $A$ يو سټ وي، نو $\emptyset = \Setabs{x \in A}{x \neq x}$ د بېلونې له مخې شتون لري.
\end{proof}

source:
\begin{prop}
$A \setminus B$ exists for any sets $A$ and $B$
\end{prop}

target:
\begin{prop}
$A \setminus B$ د هر دوو سټونو $A$ او $B$ دپاره شتون لري.
\end{prop}

source:
\begin{proof}
$A \setminus B = \Setabs{x \in A}{x \notin B}$ exists by Separation.
\end{proof}

target:
\begin{proof}
$A \setminus B = \Setabs{x \in A}{x \notin B}$ د بېلونې له مخې شتون لري.
\end{proof}

source:
\begin{prop}\ollabel{prop:intersectionsexist}
If $A \neq \emptyset$, then $\bigcap A = \Setabs{x}{(\forall y \in A)x \in y}$ exists.
\end{prop}

target:
\begin{prop}\ollabel{prop:intersectionsexist}
که $A \neq \emptyset$ وي، نو $\bigcap A = \Setabs{x}{(\forall y \in A)x \in y}$ شتون لري.
\end{prop}

source:
\begin{proof}
Let $A \neq \emptyset$, so there is some $c \in A$. Then $\bigcap A =
\Setabs{x}{(\forall y \in A)x \in y} = \Setabs{x \in c}{(\forall y \in
A)x \in y}$, which exists by Separation.
\end{proof}

target:
\begin{proof}
$A \neq \emptyset$ وګرځوئ؛ نو يو $c \in A$ شته. بيا
$\bigcap A =
\Setabs{x}{(\forall y \in A)x \in y} = \Setabs{x \in c}{(\forall y \in
A)x \in y}$ د بېلونې له مخې شتون لري.
\end{proof}

source:
\begin{prop}\ollabel{prop:pairsconsequences}
For any sets $a$ and $b$, the following sets exist:
	\begin{enumerate}
		\item\ollabel{singleton} $\{a\}$
		\item\ollabel{binunion} $a \cup b$
		\item\ollabel{tuples} $\tuple{a, b}$
	\end{enumerate}
\end{prop}

target:
\begin{prop}\ollabel{prop:pairsconsequences}
د هر دوو سټونو $a$ او $b$ دپاره لاندې سټونه شتون لري:
	\begin{enumerate}
		\item\ollabel{singleton} $\{a\}$
		\item\ollabel{binunion} $a \cup b$
		\item\ollabel{tuples} $\tuple{a, b}$
	\end{enumerate}
\end{prop}

source:
\begin{proof}
\olref{singleton}. By Pairs, $\{a, a\}$ exists, which is $\{a\}$ by
Extensionality.

target:
\begin{proof}
\olref{singleton}. د جوړو له مخې $\{a, a\}$ شتون لري، چې د
غړو له مخې د برابرۍ په اساس هماغه $\{a\}$ دے.

source:
\begin{prob}
Show that, for any sets $a, b, c$, the set $\{a, b, c\}$ exists.
\end{prob}

target:
\begin{prob}
وښيئ چې د هر درېو سټونو $a, b, c$ دپاره سټ $\{a, b, c\}$ شتون لري.
\end{prob}

source:
\begin{prob}
Show that, for any sets $a_1, \ldots, a_n$, the set $\{a_1, \ldots,
a_n\}$ exists.
\end{prob}

target:
\begin{prob}
وښيئ چې د هرې لړۍ سټونو $a_1, \ldots, a_n$ دپاره سټ $\{a_1, \ldots,
a_n\}$ شتون لري.
\end{prob}
